pe="hidden" name="payment_method" id="form_payment_method" value="{{ old('payment_method') }}"><input type="hidden" name="bank_option" id="form_bank_option" value="{{ old('bank_option') }}"><button type="submit" class="btn btn-success rounded-pill w-100 mt-3 fw-bold" id="submit-btn">Bayar Sekarang</button></form></div></div></div>
