<script>
document.addEventListener('DOMContentLoaded', function() { const deliveryOption = document.getElementById('delivery_day_selector'); const datePickerContainer = document.getElementById('date_picker_container'); const datePicker = document.getElementById('date_picker'); const finalDeliveryDay = document.getElementById('final_delivery_day'); function setTodayDate() { const today = new Date(); const yyyy = today.getFullYear(); const mm = String(today.getMonth() + 1).padStart(2, '0'); const dd = String(today.getDate()).padStart(2, '0'); return `${yyyy}-${mm}-${dd}`; } finalDeliveryDay.value = setTodayDate(); deliveryOption.addEventListener('change', function () { if (this.value === 'choose_date') { datePickerContainer.style.display = 'block'; finalDeliveryDay.value = ''; } else { datePickerContainer.style.display = 'none'; finalDeliveryDay.value = setTodayDate(); } }); datePicker.addEventListener('change', function () { finalDeliveryDay.value = this.value; }); const deliveryTime = document.getElementById('delivery_time'); document.getElementById('form_delivery_time').value = deliveryTime.value; const form = document.getElementById('payment-form'); form.addEventListener('submit', function (e) { const finalDeliveryDay = document.getElementById('final_delivery_day'); const deliveryTime = document.getElementById('delivery_time'); const paymentMethodHidden = document.getElementById('form_payment_method'); const bankOptionHidden = document.getElementById('form_bank_option'); let isValid = true; if (!finalDeliveryDay.value) { alert('Harap pilih tanggal pengiriman.'); e.preventDefault(); return; } if (!paymentMethodHidden.value) { alert('Harap pilih metode pembayaran.'); e.preventDefault(); return; } if (paymentMethodHidden.value === 'transfer_bank' && !bankOptionHidden.value) { alert('Harap pilih bank untuk transfer.'); e.preventDefault(); return; } if (!isValid) { e.preventDefault(); return false; } const deliveryTimeValue = deliveryTime.options[deliveryTime.selectedIndex].value; document.getElementById('form_delivery_time').value = deliveryTimeValue; }); document.querySelectorAll('.payment-method-btn').forEach(btn => { btn.addEventListener('click', function () { const method = this.dataset.method; document.getElementById('form_payment_method').value = method; document.getElementById('transfer-bank-section').classList.add('d-none'); document.getElementById('other-method-section').classList.add('d-none'); if (method === 'transfer_bank') { document.getElementById('transfer-bank-section').classList.remove('d-none'); } else { document.getElementById('other-method-section').classList.remove('d-none'); document.getElementById('method-desc').textContent = 'Anda memilih metode: ' + method.toUpperCase().replace('_', ' '); } document.querySelectorAll('.payment-method-btn').forEach(btn => btn.classList.remove('btn-success')); this.classList.add('btn-success'); }); }); document.querySelectorAll('.bank-radio').forEach(radio => { radio.addEventListener('change', function () { document.getElementById('form_bank_option').value = this.value; }); }); });
</script>
